import{_ as i,c as a,o as e,a0 as o}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively.","frontmatter":{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively."},"headers":[],"relativePath":"it/blog/team-communication.md","filePath":"it/blog/team-communication.md"}');const l=i({name:"it/blog/team-communication.md"},[["render",function(i,n,l,r,t,s){return e(),a("div",null,[...n[0]||(n[0]=[o('<h1 id="comunicazione-sotto-pressione" tabindex="-1">Comunicazione sotto pressione <a class="header-anchor" href="#comunicazione-sotto-pressione" aria-label="Permalink to &quot;Comunicazione sotto pressione&quot;">​</a></h1><p>Nel gioco delle bocce, la comunicazione può fare la differenza tra il successo e il fallimento di una squadra. Le parole giuste al momento giusto creano fiducia e chiarezza. Le parole sbagliate – o il silenzio quando servono – possono mandare in tilt anche squadre molto abili.</p><h2 id="perche-la-comunicazione-e-importante" tabindex="-1">Perché la comunicazione è importante <a class="header-anchor" href="#perche-la-comunicazione-e-importante" aria-label="Permalink to &quot;Perché la comunicazione è importante&quot;">​</a></h2><p>Le squadre di bocce affrontano sfide comunicative uniche:</p><ul><li>Le decisioni devono essere prese rapidamente</li><li>La pressione influenza il modo in cui parliamo e ascoltiamo</li><li>I segnali non verbali sono visibili agli avversari</li><li>Le prestazioni individuali influenzano le dinamiche di squadra</li></ul><p>Una comunicazione efficace crea:</p><ul><li>Comprensione condivisa della strategia</li><li>Sostegno reciproco e fiducia</li><li>Decisioni rapide e chiare</li><li>Resilienza nei momenti difficili</li></ul><h2 id="i-principi-della-comunicazione" tabindex="-1">I principi della comunicazione <a class="header-anchor" href="#i-principi-della-comunicazione" aria-label="Permalink to &quot;I principi della comunicazione&quot;">​</a></h2><h3 id="_1-chiarezza-sulla-quantita" tabindex="-1">1. Chiarezza sulla quantità <a class="header-anchor" href="#_1-chiarezza-sulla-quantita" aria-label="Permalink to &quot;1. Chiarezza sulla quantità&quot;">​</a></h3><p>Sotto pressione, meno è meglio. Una comunicazione chiara e concisa è meglio di lunghe discussioni:</p><p><strong>Invece di:</strong> &quot;Penso che forse dovremmo provare a indicare qui, ma non ne sono sicuro. Cosa ne pensi? Il terreno sembra insidioso...&quot;</p><p><strong>Di&#39;:</strong> &quot;Indico il lato sinistro. Lì il terreno è migliore.&quot;</p><h3 id="_2-inquadramento-positivo" tabindex="-1">2. Inquadramento positivo <a class="header-anchor" href="#_2-inquadramento-positivo" aria-label="Permalink to &quot;2. Inquadramento positivo&quot;">​</a></h3><p>Inquadrare le comunicazioni in modo costruttivo:</p><p><strong>Invece di:</strong> &quot;Non perderti questo&quot; <strong>Di&#39;:</strong> &quot;Ce la puoi fare, fidati del tuo tiro&quot;</p><p><strong>Invece di:</strong> &quot;È stato terribile&quot; <strong>Di&#39;:</strong> &quot;Scuotilo di dosso, il prossimo è il turno&quot;</p><h3 id="_3-focus-sul-presente" tabindex="-1">3. Focus sul presente <a class="header-anchor" href="#_3-focus-sul-presente" aria-label="Permalink to &quot;3. Focus sul presente&quot;">​</a></h3><p>Mantieni la comunicazione focalizzata su ciò che verrà dopo, non su ciò che è già passato:</p><p><strong>Invece di:</strong> &quot;Perché l&#39;hai lanciato lì?&quot; <strong>Di&#39;:</strong> &quot;Ok, qual è la nostra opzione migliore adesso?&quot;</p><h3 id="_4-linguaggio-di-proprieta" tabindex="-1">4. Linguaggio di proprietà <a class="header-anchor" href="#_4-linguaggio-di-proprieta" aria-label="Permalink to &quot;4. Linguaggio di proprietà&quot;">​</a></h3><p>Usa le affermazioni in prima persona per le tue azioni, in seconda persona per le situazioni di squadra:</p><ul><li>&quot;Farò questo scatto&quot;</li><li>&quot;Dobbiamo proteggere il punto&quot;</li><li>&quot;Penso che dovremmo...&quot;</li></ul><h2 id="cosa-comunicare" tabindex="-1">Cosa comunicare <a class="header-anchor" href="#cosa-comunicare" aria-label="Permalink to &quot;Cosa comunicare&quot;">​</a></h2><h3 id="prima-di-ogni-fine" tabindex="-1">Prima di ogni fine <a class="header-anchor" href="#prima-di-ogni-fine" aria-label="Permalink to &quot;Prima di ogni fine&quot;">​</a></h3><ul><li><strong>Discussione sulla strategia</strong>: breve allineamento sull&#39;approccio</li><li><strong>Chiarezza del ruolo</strong>: chi fa cosa</li><li><strong>Osservazioni del terreno</strong>: Condizioni rilevanti</li></ul><h3 id="durante-il-gioco" tabindex="-1">Durante il gioco <a class="header-anchor" href="#durante-il-gioco" aria-label="Permalink to &quot;Durante il gioco&quot;">​</a></h3><ul><li><strong>Decisioni</strong>: Dichiarazione chiara dell&#39;azione prevista</li><li><strong>Supporto</strong>: Incoraggiamento prima dei lanci</li><li><strong>Informazioni</strong>: Osservazioni rilevanti sul terreno o sugli avversari</li></ul><h3 id="dopo-i-lanci" tabindex="-1">Dopo i lanci <a class="header-anchor" href="#dopo-i-lanci" aria-label="Permalink to &quot;Dopo i lanci&quot;">​</a></h3><ul><li><strong>Riconoscimento</strong>: Breve riconoscimento (positivo o negativo)</li><li><strong>Adeguamento</strong>: Eventuali modifiche strategiche necessarie</li><li><strong>Reimposta</strong>: aiuta il compagno di squadra a riconcentrarsi</li></ul><h2 id="cosa-non-comunicare" tabindex="-1">Cosa NON comunicare <a class="header-anchor" href="#cosa-non-comunicare" aria-label="Permalink to &quot;Cosa NON comunicare&quot;">​</a></h2><h3 id="evitare-durante-i-momenti-di-pressione" tabindex="-1">Evitare durante i momenti di pressione <a class="header-anchor" href="#evitare-durante-i-momenti-di-pressione" aria-label="Permalink to &quot;Evitare durante i momenti di pressione&quot;">​</a></h3><ul><li>Istruzioni tecniche (&quot;Tieni il gomito dentro&quot;)</li><li>Critica dei lanci passati</li><li>Espressioni di frustrazione</li><li>Dubbi sulle capacità del compagno di squadra</li><li>Analisi eccessiva</li></ul><h3 id="evitare-in-generale" tabindex="-1">Evitare in generale <a class="header-anchor" href="#evitare-in-generale" aria-label="Permalink to &quot;Evitare in generale&quot;">​</a></h3><ul><li>Linguaggio della colpa</li><li>Sarcasmo o aggressività passiva</li><li>Confronti con altri giocatori</li><li>Previsioni di fallimento</li></ul><h2 id="comunicazione-non-verbale" tabindex="-1">Comunicazione non verbale <a class="header-anchor" href="#comunicazione-non-verbale" aria-label="Permalink to &quot;Comunicazione non verbale&quot;">​</a></h2><p>Il tuo linguaggio del corpo parla ad alta voce:</p><h3 id="segnali-positivi" tabindex="-1">Segnali positivi <a class="header-anchor" href="#segnali-positivi" aria-label="Permalink to &quot;Segnali positivi&quot;">​</a></h3><ul><li>Contatto visivo con i compagni di squadra</li><li>Postura aperta e rilassata</li><li>Annuendo e riconoscendo</li><li>Movimenti calmi e costanti</li></ul><h3 id="segnali-negativi-da-evitare" tabindex="-1">Segnali negativi (da evitare) <a class="header-anchor" href="#segnali-negativi-da-evitare" aria-label="Permalink to &quot;Segnali negativi (da evitare)&quot;">​</a></h3><ul><li>Roteare gli occhi o sospirare</li><li>Allontanarsi dai compagni di squadra</li><li>Braccia incrociate o postura chiusa</li><li>Frustrazione visibile</li></ul><h3 id="compagni-di-squadra-di-lettura" tabindex="-1">Compagni di squadra di lettura <a class="header-anchor" href="#compagni-di-squadra-di-lettura" aria-label="Permalink to &quot;Compagni di squadra di lettura&quot;">​</a></h3><p>Impara a riconoscere quando i tuoi compagni di squadra hanno bisogno di:</p><ul><li><strong>Spazio</strong>: Stanno elaborando, non interromperli</li><li><strong>Supporto</strong>: Stanno lottando, offri incoraggiamento</li><li><strong>Informazioni</strong>: Sono incerti, fornire chiarezza</li><li><strong>Energia</strong>: Sono piatti, portano entusiasmo</li></ul><h2 id="ruoli-di-comunicazione" tabindex="-1">Ruoli di comunicazione <a class="header-anchor" href="#ruoli-di-comunicazione" aria-label="Permalink to &quot;Ruoli di comunicazione&quot;">​</a></h2><h3 id="il-puntatore" tabindex="-1">Il puntatore <a class="header-anchor" href="#il-puntatore" aria-label="Permalink to &quot;Il puntatore&quot;">​</a></h3><ul><li>Comunica la tua lettura del terreno</li><li>Indica chiaramente il posizionamento previsto</li><li>Chiedi un contributo quando sei incerto</li></ul><h3 id="il-tiratore" tabindex="-1">Il tiratore <a class="header-anchor" href="#il-tiratore" aria-label="Permalink to &quot;Il tiratore&quot;">​</a></h3><ul><li>Conferma la selezione del target</li><li>Comunicare il livello di fiducia</li><li>Richiedi informazioni sugli angoli</li></ul><h3 id="il-milieu-capitano" tabindex="-1">Il Milieu/Capitano <a class="header-anchor" href="#il-milieu-capitano" aria-label="Permalink to &quot;Il Milieu/Capitano&quot;">​</a></h3><ul><li>Facilitare le discussioni di gruppo</li><li>Prendi decisioni definitive quando necessario</li><li>Gestire l&#39;energia e la concentrazione del team</li></ul><h2 id="situazioni-di-pressione" tabindex="-1">Situazioni di pressione <a class="header-anchor" href="#situazioni-di-pressione" aria-label="Permalink to &quot;Situazioni di pressione&quot;">​</a></h2><h3 id="quando-dietro" tabindex="-1">Quando dietro <a class="header-anchor" href="#quando-dietro" aria-label="Permalink to &quot;Quando dietro&quot;">​</a></h3><ul><li>Concentrarsi sulla soluzione</li><li>Mantenere l&#39;energia positiva</li><li>Evitare la colpa o la frustrazione</li><li>Festeggia le piccole vittorie</li></ul><h3 id="quando-avanti" tabindex="-1">Quando avanti <a class="header-anchor" href="#quando-avanti" aria-label="Permalink to &quot;Quando avanti&quot;">​</a></h3><ul><li>Rimani concentrato, evita l&#39;autocompiacimento</li><li>Mantenere la comunicazione coerente</li><li>Non cambiare ciò che funziona</li></ul><h3 id="match-point-loro" tabindex="-1">Match Point (loro) <a class="header-anchor" href="#match-point-loro" aria-label="Permalink to &quot;Match Point (loro)&quot;">​</a></h3><ul><li>Riconoscere brevemente la pressione</li><li>Concentrarsi sul processo</li><li>Sostenetevi a vicenda visibilmente</li></ul><h3 id="match-point-il-nostro" tabindex="-1">Match Point (il nostro) <a class="header-anchor" href="#match-point-il-nostro" aria-label="Permalink to &quot;Match Point (il nostro)&quot;">​</a></h3><ul><li>Mantieni la calma e la concentrazione</li><li>Evitare festeggiamenti prematuri</li><li>Eseguire normalmente</li></ul><h2 id="sviluppo-delle-capacita-comunicative" tabindex="-1">Sviluppo delle capacità comunicative <a class="header-anchor" href="#sviluppo-delle-capacita-comunicative" aria-label="Permalink to &quot;Sviluppo delle capacità comunicative&quot;">​</a></h2><h3 id="in-pratica" tabindex="-1">In pratica <a class="header-anchor" href="#in-pratica" aria-label="Permalink to &quot;In pratica&quot;">​</a></h3><ul><li>Esercitati a comunicare durante l&#39;allenamento</li><li>Dare e ricevere feedback sulla comunicazione</li><li>Sperimentare approcci diversi</li></ul><h3 id="accordi-di-squadra" tabindex="-1">Accordi di squadra <a class="header-anchor" href="#accordi-di-squadra" aria-label="Permalink to &quot;Accordi di squadra&quot;">​</a></h3><p>Stabilire le norme del team:</p><ul><li>Come gestiamo i disaccordi</li><li>Come si presenta il supporto</li><li>Quando parlare e quando stare zitti</li></ul><h3 id="revisione-post-partita" tabindex="-1">Revisione post-partita <a class="header-anchor" href="#revisione-post-partita" aria-label="Permalink to &quot;Revisione post-partita&quot;">​</a></h3><p>Discutere la comunicazione:</p><ul><li>Cosa ha funzionato bene?</li><li>Cosa si potrebbe migliorare?</li><li>Ci sono malintesi da chiarire?</li></ul><h2 id="quando-la-comunicazione-si-interrompe" tabindex="-1">Quando la comunicazione si interrompe <a class="header-anchor" href="#quando-la-comunicazione-si-interrompe" aria-label="Permalink to &quot;Quando la comunicazione si interrompe&quot;">​</a></h2><h3 id="nel-momento" tabindex="-1">Nel momento <a class="header-anchor" href="#nel-momento" aria-label="Permalink to &quot;Nel momento&quot;">​</a></h3><ol><li>Fai un respiro</li><li>Ripartiamo con una semplice affermazione: &quot;Concentriamoci su questo lancio&quot;</li><li>Ritorno alle basi: chiaro, positivo, presente</li></ol><h3 id="dopo-la-partita" tabindex="-1">Dopo la partita <a class="header-anchor" href="#dopo-la-partita" aria-label="Permalink to &quot;Dopo la partita&quot;">​</a></h3><ul><li>Affrontare i problemi con calma</li><li>Concentrati sui comportamenti, non sulle personalità</li><li>Concordare i miglioramenti</li><li>Andiamo avanti insieme</li></ul><h2 id="il-supporto-silenzioso" tabindex="-1">Il supporto silenzioso <a class="header-anchor" href="#il-supporto-silenzioso" aria-label="Permalink to &quot;Il supporto silenzioso&quot;">​</a></h2><p>A volte la migliore comunicazione è la presenza:</p><ul><li>In piedi con un compagno di squadra in difficoltà</li><li>Una mano sulla spalla</li><li>Un cenno di fiducia</li><li>Semplicemente esserci</li></ul><p>Le parole non sono sempre necessarie. La connessione sì.</p><hr><p>| <em>Correlato: <a href="/it/education/team-player/">Dinamiche di squadra</a> | <a href="/it/istruzione/giocatore-di-squadra/comunicazione">Comunicazione</a> | <a href="/it/educazione/forza-mentale/gestire-la-pressione">Gestire la pressione</a></em> |</p>',79)])])}]]);export{n as __pageData,l as default};
